'use strict';

const express = require('express');
const { generateId } = require('../utils/id');
const { sendError } = require('../utils/errors');

const ROOMS_COLLECTION = 'rooms';

/**
 * Creates the Rooms Express router and WebSocket attachment helper.
 * 
 * @param {object} options
 * @param {object} options.storage - Conforming storage adapter
 * @returns {import('express').Router & { attachWebSocket: Function }}
 */
function createRoomsRouter({ storage }) {
  const router = express.Router();
  router.use(express.json());

  /**
   * POST /
   * Create a new room.
   * Body: { name: string, maxPlayers?: number }
   */
  router.post('/', async (req, res, next) => {
    try {
      const { name, maxPlayers = 8 } = req.body || {};

      if (!name || typeof name !== 'string' || name.trim().length === 0) {
        return sendError(res, 400, 'Room "name" is required and must be a non-empty string');
      }

      const room = {
        id: generateId('r_'),
        name: name.trim(),
        maxPlayers: typeof maxPlayers === 'number' ? maxPlayers : 8,
        members: [],
        createdAt: new Date().toISOString()
      };

      await storage.set(ROOMS_COLLECTION, room.id, room);

      return res.status(201).json(room);
    } catch (err) {
      next(err);
    }
  });

  /**
   * GET /
   * List all active rooms.
   */
  router.get('/', async (req, res, next) => {
    try {
      const rooms = await storage.list(ROOMS_COLLECTION);
      return res.status(200).json(rooms);
    } catch (err) {
      next(err);
    }
  });

  /**
   * GET /:id
   * Get room details by ID.
   */
  router.get('/:id', async (req, res, next) => {
    try {
      const { id } = req.params;
      const room = await storage.get(ROOMS_COLLECTION, id);

      if (!room) {
        return sendError(res, 404, 'Room not found');
      }

      return res.status(200).json(room);
    } catch (err) {
      next(err);
    }
  });

  /**
   * Attaches a WebSocket server (using `ws` loaded lazily) to an HTTP server instance.
   * Allows clients to connect, join rooms, and broadcast messages.
   * 
   * @param {import('http').Server} server 
   * @param {string} [path='/ws/rooms']
   */
  router.attachWebSocket = function attachWebSocket(server, path = '/ws/rooms') {
    let WebSocketServer;
    try {
      const wsPkg = require('ws');
      WebSocketServer = wsPkg.Server || wsPkg.WebSocketServer;
    } catch (err) {
      throw new Error(
        'To use WebSocket rooms, please install the "ws" package: "npm install ws"\n' +
        `Underlying error: ${err.message}`
      );
    }

    const wss = new WebSocketServer({ server, path });
    // Map roomId -> Set of client sockets
    const roomClients = new Map();

    wss.on('connection', (ws) => {
      let currentRoomId = null;
      let currentPlayerId = null;

      ws.on('message', async (raw) => {
        try {
          const payload = JSON.parse(raw.toString());
          const { action, roomId, playerId, message } = payload;

          if (action === 'join') {
            if (!roomId || !playerId) {
              return ws.send(JSON.stringify({ error: 'roomId and playerId required to join' }));
            }

            const room = await storage.get(ROOMS_COLLECTION, roomId);
            if (!room) {
              return ws.send(JSON.stringify({ error: 'Room not found' }));
            }

            currentRoomId = roomId;
            currentPlayerId = playerId;

            if (!roomClients.has(roomId)) {
              roomClients.set(roomId, new Set());
            }
            roomClients.get(roomId).add(ws);

            // Update room members if not already present
            if (!room.members.includes(playerId)) {
              room.members.push(playerId);
              await storage.set(ROOMS_COLLECTION, roomId, room);
            }

            // Broadcast join notice
            broadcast(roomId, { event: 'player_joined', roomId, playerId, members: room.members });
          } else if (action === 'message') {
            if (!currentRoomId) {
              return ws.send(JSON.stringify({ error: 'You are not in any room' }));
            }
            broadcast(currentRoomId, {
              event: 'chat_message',
              roomId: currentRoomId,
              senderId: currentPlayerId,
              message,
              sentAt: new Date().toISOString()
            });
          } else if (action === 'leave') {
            cleanup();
          }
        } catch {
          ws.send(JSON.stringify({ error: 'Invalid JSON message' }));
        }
      });

      function cleanup() {
        if (currentRoomId && roomClients.has(currentRoomId)) {
          const clients = roomClients.get(currentRoomId);
          clients.delete(ws);
          if (clients.size === 0) {
            roomClients.delete(currentRoomId);
          } else {
            broadcast(currentRoomId, {
              event: 'player_left',
              roomId: currentRoomId,
              playerId: currentPlayerId
            });
          }
        }
        currentRoomId = null;
        currentPlayerId = null;
      }

      function broadcast(roomId, data) {
        const clients = roomClients.get(roomId);
        if (!clients) return;
        const msg = JSON.stringify(data);
        for (const client of clients) {
          if (client.readyState === 1) { // 1 = OPEN
            client.send(msg);
          }
        }
      }

      ws.on('close', cleanup);
      ws.on('error', cleanup);
    });

    return wss;
  };

  return router;
}

module.exports = {
  createRoomsRouter
};
